alter table public.vehicle_image_assets add column if not exists service_context text; create or replace function public.guard_vehicle_image_review_baseline() returns trigger language plpgsql security invoker set search_path = public, pg_temp as $$ declare b public.vehicle_image_review_baselines%rowtype; begin select * into b from public.vehicle_image_review_baselines where asset_id=old.id; if not found then return coalesce(new,old); end if; if tg_op='DELETE' then raise exception 'Reviewed vehicle image asset % cannot be deleted while baseline exists',old.id; end if; if new.image_path is distinct from b.image_path or new.operator is distinct from old.operator or new.vehicle_type is distinct from old.vehicle_type or new.asset_status is distinct from old.asset_status then raise exception 'Reviewed vehicle image asset % has a protected basic identity',old.id; end if; if b.metadata_lock_eligible and (new.formation_id is distinct from old.formation_id or new.car_id is distinct from old.car_id or new.is_generic is distinct from old.is_generic or new.asset_scope is distinct from old.asset_scope or new.livery is distinct from old.livery or new.theme is distinct from old.theme or new.subseries is distinct from old.subseries or new.service_context is distinct from old.service_context) then raise exception 'Reviewed vehicle image asset % has protected detailed identity',old.id; end if; return new; end $$; comment on column public.vehicle_image_assets.service_context is 'Line or region depicted by vehicle asset; not proof of train assignment or evidence of current operation.'
